PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE runs(
            id INTEGER PRIMARY KEY, flavor TEXT, client_dir TEXT, started TEXT, finished TEXT,
            total INTEGER, ok INTEGER, failed INTEGER, UNIQUE(flavor, started));
CREATE TABLE failures(
            run_id INTEGER REFERENCES runs(id), guide_id TEXT, error TEXT);
CREATE TABLE feature_runs(
    id INTEGER PRIMARY KEY,
    flavor        TEXT,
    client_dir    TEXT,
    build         TEXT,   -- client TOC/interface number
    addon_version TEXT,
    at            TEXT,
    passed        INTEGER,
    failed        INTEGER,
    UNIQUE(flavor, at));
CREATE TABLE feature_checks(
    run_id  INTEGER REFERENCES feature_runs(id),
    feature TEXT,   -- beacon | account | core
    name    TEXT,
    pass    INTEGER,
    detail  TEXT);
CREATE TABLE route_sweep(
  flavor TEXT, at TEXT, guide TEXT, name TEXT, type TEXT, faction TEXT, zone INTEGER, zone_name TEXT,
  steps INTEGER, located INTEGER, unknown_zone INTEGER, window INTEGER, order_ok INTEGER, order_reason TEXT,
  opt_cost REAL, author_cost REAL, route_ok TEXT, route TEXT, error TEXT, PRIMARY KEY(flavor, guide));
CREATE TABLE ingame_sweeps(
            id INTEGER PRIMARY KEY, flavor TEXT, client_dir TEXT, started TEXT, finished TEXT, location TEXT,
            total INTEGER, steps INTEGER, located INTEGER, precedence INTEGER, slower INTEGER, no_route INTEGER,
            ui_empty INTEGER, load_fail INTEGER, no_route_instance INTEGER DEFAULT 0, UNIQUE(flavor, started));
CREATE TABLE ingame_sweep_errors(
            run_id INTEGER REFERENCES ingame_sweeps(id), guide_id TEXT, error TEXT);
CREATE TABLE ingame_sweep_partials(
            id INTEGER PRIMARY KEY, flavor TEXT, client_dir TEXT, started TEXT, collected TEXT, location TEXT,
            total INTEGER, done INTEGER, steps INTEGER, located INTEGER, precedence INTEGER, slower INTEGER,
            no_route INTEGER, ui_empty INTEGER, load_fail INTEGER, UNIQUE(flavor, started));
CREATE TABLE run_partials(
            id INTEGER PRIMARY KEY, flavor TEXT, client_dir TEXT, started TEXT, collected TEXT,
            total INTEGER, done INTEGER, failed INTEGER, UNIQUE(flavor, started));
CREATE TABLE route_sweep_from(
  flavor TEXT, origin_map INTEGER, faction TEXT, at TEXT, guide TEXT, name TEXT, type TEXT, steps INTEGER, located INTEGER,
  order_ok INTEGER, opt_cost REAL, author_cost REAL, route_ok TEXT, route TEXT, error TEXT, PRIMARY KEY(flavor, origin_map, faction, guide));
CREATE TABLE guide_type_audit (
        at TEXT, rev TEXT, flavor TEXT, type TEXT, guides INT, steps INT, located INT,
        unlocated INT, nocoord_guides INT, pct_located REAL);
CREATE TABLE gold_circuits (
        at TEXT, rev TEXT, flavor TEXT, metric TEXT, value REAL);
CREATE TABLE vplayer_guides(
  flavor TEXT, at TEXT, guide TEXT, name TEXT, type TEXT, faction TEXT, zone TEXT, zone_name TEXT,
  steps INTEGER, simulated INTEGER, auto INTEGER, manual INTEGER, stalls INTEGER, forced INTEGER,
  laps INTEGER, yards REAL, seconds REAL, no_route INTEGER, finished INTEGER,
  manual_reason TEXT, error TEXT, PRIMARY KEY(flavor, guide));
CREATE TABLE vplayer_stalls(
  flavor TEXT, at TEXT, guide TEXT, step INTEGER, action TEXT, title TEXT, qid TEXT, zone TEXT, coords TEXT,
  PRIMARY KEY(flavor, guide, step));
CREATE TABLE vplayer_runs(
  flavor TEXT, at TEXT, guides INTEGER, finished INTEGER, steps INTEGER, simulated INTEGER,
  auto INTEGER, manual INTEGER, stalls INTEGER, stalled_guides INTEGER, errors INTEGER,
  no_route INTEGER, yards REAL, hours REAL, PRIMARY KEY(flavor, at));
CREATE TABLE coverage (flavor text, category text, label text, total int,
                   covered int, missing int, located int, measured text, primary key (flavor, category, label));
CREATE TABLE coverage_missing (flavor text, category text, id int);
CREATE TABLE noroute_rerun (label text, flavor text, guide text, steps int, no_route_before int, no_route_after int, finished int, stalls int);
CREATE TABLE noroute_steps (label text, flavor text, guide text, step int, action text, from_map text, to_map text, to_name text);
CREATE VIEW feature_matrix AS
    SELECT r.flavor, c.feature, c.name, MAX(c.pass) AS pass, MAX(r.at) AS last_run
    FROM feature_runs r JOIN feature_checks c ON c.run_id = r.id
    GROUP BY r.flavor, c.feature, c.name;
COMMIT;
